const IDEAS = [
{id:"kahneman-1",d:0,en:"Thinking, Fast and Slow",a:"Daniel Kahneman",t:"عقلك يعمل بنظامين",
x:"يرى كانمان، الحائز على جائزة نوبل في الاقتصاد، أن في عقلك نظامين. النظام الأول سريع وتلقائي يعمل دون جهد: هو الذي يجيبك فورًا عن اثنين زائد اثنين، ويقود السيارة في طريق خالٍ، ويقرأ الغضب في وجه شخص أمامك. والنظام الثاني بطيء ومتأنٍ ويحتاج إلى تركيز: هو الذي تستدعيه لتحسب سبعة عشر في أربعة وعشرين، أو لتملأ استمارة ضرائب.\n\nجرّب هذا السؤال: مضرب وكرة ثمنهما معًا دولار وعشرة سنتات، والمضرب أغلى من الكرة بدولار واحد. كم ثمن الكرة؟ الجواب الذي يقفز إلى ذهنك هو عشرة سنتات، وهو خطأ؛ لأن المضرب حينها سيكون بدولار وعشرة سنتات، والمجموع دولار وعشرين. الصحيح خمسة سنتات. ووجد كانمان أن أكثر من نصف طلاب جامعات مرموقة أخطأوا في هذا السؤال.\n\nالمشكلة ليست في النظام الأول، فهو ضروري وسريع، بل في أن النظام الثاني كسول فيقبل إجاباته دون فحص. الدرس العملي: في القرارات المهمة، توقّف واسأل نفسك هل اخترت هذا الجواب لأنه صحيح أم لأنه سهل."},
{id:"frankl-1",d:0,en:"Man's Search for Meaning",a:"Viktor E. Frankl",t:"الحرية الأخيرة",
x:"كان فيكتور فرانكل طبيبًا نفسيًا نمساويًا قضى سنوات في معسكرات الاعتقال النازية، ومنها أوشفيتز. هناك لاحظ أن من تمسّكوا بسبب يعيشون من أجله كانوا أقدر على الصمود من غيرهم، حتى لو كانوا أضعف جسديًا.\n\nوقد عاش فرانكل هذا بنفسه: كان يتمسّك بأمل أن يرى زوجته مرة أخرى، ويتخيّل حواراته معها في البرد والجوع. وكان قد فقد مخطوطة كتاب عمل عليه سنوات حين صودرت ملابسه، فصار هدفه أن يخرج حيًا ليعيد كتابتها. بل كان يتخيّل نفسه بعد الحرب يلقي محاضرة عن علم نفس المعسكرات، فيتحوّل الألم الذي يعيشه إلى مادة يدرسها.\n\nوخلص إلى أن الإنسان قد يُسلب كل شيء إلا شيئًا واحدًا: حريته في اختيار موقفه تجاه ما يحدث له. واستشهد بفكرة نيتشه: من يملك سببًا يعيش من أجله يستطيع أن يتحمّل أي ظروف تقريبًا. ومن هنا أسّس منهجه العلاجي القائم على أن البحث عن المعنى هو الدافع الأعمق في حياة الإنسان، أقوى من البحث عن المتعة أو السلطة."},
{id:"cialdini-1",d:0,en:"Influence: The Psychology of Persuasion",a:"Robert B. Cialdini",t:"قاعدة ردّ الجميل",
x:"من أقوى أدوات الإقناع التي يشرحها تشالديني قاعدة المعاملة بالمثل: حين يعطيك أحد شيئًا، تشعر بضغط داخلي لأن تردّ له الجميل، حتى لو لم تطلب ما أعطاك. ويذكر مثال جماعة دينية كانت تجمع التبرعات في المطارات الأمريكية: يضع أفرادها وردة في يد المسافر أولًا، ثم يطلبون التبرع. كثيرون لم يكونوا يريدون الوردة أصلًا، ومع ذلك يدفعون، ثم يرمونها في أقرب سلة.\n\nوللقاعدة صورة أذكى يسمّيها تشالديني الرفض ثم التراجع. يحكي أن فتى كشافة أوقفه في الشارع وطلب منه أن يشتري تذكرتين لعرض بخمسة دولارات للتذكرة. رفض تشالديني، فقال الفتى: إذن اشترِ قطعتين من الشوكولاتة بدولار واحد فقط. فاشترى، رغم أنه لا يحب الشوكولاتة. السبب أن الفتى قدّم تنازلًا، فشعر هو بأن عليه أن يقدّم تنازلًا مقابلًا.\n\nلهذا توزّع المتاجر عينات مجانية، ولهذا يبدأ البائع أحيانًا بعرض باهظ. انتبه: الهدية الصغيرة غير المطلوبة أو التراجع المفاجئ قد يكونان مقدمة لطلب كان هو الهدف من البداية."},
{id:"clear-1",d:1,en:"Atomic Habits",a:"James Clear",t:"قوة الواحد في المئة",
x:"يقول جيمس كلير إن التغييرات الصغيرة جدًا تبدو بلا قيمة في يومها، لكنها تتراكم مثل الفائدة المركّبة. لو تحسّنت بنسبة واحد في المئة فقط كل يوم لمدة سنة، فستكون في نهايتها أفضل بنحو سبعة وثلاثين ضعفًا. ولو تراجعت بالنسبة نفسها يوميًا، لاقتربت من الصفر.\n\nلذلك ينصح بأن تهتم بالنظام لا بالهدف: الفائز والخاسر في أي سباق لهما الهدف نفسه، والفرق في العادات اليومية التي يمارسها كل منهما. ابدأ بعادة صغيرة إلى حد يبدو مضحكًا، كصفحة واحدة في اليوم أو تمرين لدقيقتين، ثم دع التراكم يعمل لصالحك."},
{id:"covey-1",d:1,en:"The 7 Habits of Highly Effective People",a:"Stephen R. Covey",t:"دائرة الاهتمام ودائرة التأثير",
x:"يرسم كوفي دائرتين: دائرة كبيرة فيها كل ما يشغلك، كالاقتصاد والأخبار وآراء الناس، وداخلها دائرة أصغر فيها ما تستطيع التأثير فيه فعلًا، كعملك ومهاراتك وطريقة ردّك على الآخرين. الشخص المبادر يصرف طاقته في دائرة التأثير، فتتسع مع الوقت. أما الشخص الانفعالي فيصرف طاقته في الشكوى مما لا يملك تغييره، فتنكمش دائرة تأثيره.\n\nوهذه هي العادة الأولى عند كوفي: أن تكون مبادرًا، أي أن تدرك أنك مسؤول عن استجابتك لما يحدث. جرّب اليوم أن تراقب كلامك: كم مرة قلت لا أستطيع، بدل أن تقول سأختار؟"},
{id:"newport-1",d:1,en:"Deep Work",a:"Cal Newport",t:"بقايا الانتباه",
x:"يستشهد نيوبورت بأبحاث الباحثة صوفي لوروي عن ظاهرة تسمّى بقايا الانتباه: عندما تنتقل من مهمة إلى أخرى، لا ينتقل انتباهك كله معك، بل يبقى جزء منه عالقًا في المهمة السابقة. لذلك فإن نظرة سريعة إلى البريد أو الهاتف كل عشر دقائق تبقي عقلك مشتتًا طوال الوقت، حتى لو بدت كل نظرة قصيرة وبريئة.\n\nويرى نيوبورت أن القدرة على التركيز العميق دون مقاطعة أصبحت نادرة، ولهذا أصبحت ذات قيمة عالية في سوق العمل. اقتراحه العملي: احجز في يومك فترات ثابتة للعمل المركّز، وأغلق خلالها كل وسائل المقاطعة."},
{id:"housel-1",d:2,en:"The Psychology of Money",a:"Morgan Housel",t:"سرّ ثروة بافيت هو الوقت",
x:"يسأل هاوسل: ما سرّ ثروة وارن بافيت؟ الجواب المعتاد هو مهارته في الاستثمار، وهذا صحيح، لكن السر الأكبر هو الوقت. اشترى بافيت أول سهم وهو في الحادية عشرة، واستمر عليه أكثر من سبعين عامًا، فجاء أكثر من خمسة وتسعين في المئة من ثروته بعد أن تجاوز الخامسة والستين من عمره.\n\nولتوضيح ذلك يجري هاوسل حسبة افتراضية: لو أن بافيت بدأ الاستثمار في الثلاثين، وتقاعد في الستين، وحقق العوائد السنوية نفسها، لكانت ثروته نحو اثني عشر مليون دولار فقط، لا عشرات المليارات. المهارة نفسها، لكن الزمن مختلف.\n\nويقارنه بالمستثمر جيم سايمونز، الذي حقق عوائد سنوية أعلى بكثير من بافيت، لكنه بدأ الاستثمار الجدي في نحو الخمسين من عمره، فبقيت ثروته أقل بكثير.\n\nهذه هي الفائدة المركّبة: النمو يبدو بطيئًا في البداية، ثم يتسارع بشكل يصعب على عقولنا تخيّله. والدرس عند هاوسل أن الاستمرار مدة طويلة دون أن تضطر إلى البيع في الأزمات أهم من محاولة تحقيق أعلى عائد في سنة واحدة."},
{id:"kiyosaki-1",d:2,en:"Rich Dad Poor Dad",a:"Robert T. Kiyosaki",t:"الأصل والالتزام",
x:"يقدّم كيوساكي تعريفًا بسيطًا: الأصل هو ما يضع المال في جيبك، والالتزام هو ما يأخذ المال من جيبك. مثال: شقة تؤجرها بثمانمئة شهريًا، وتكلّفك أقساطًا وصيانة بستمئة، هي أصل لأنها تُدخل لك مئتين كل شهر. أما سيارة جديدة اشتريتها بقرض فهي التزام، لأنها تأخذ منك القسط والتأمين والوقود وتفقد من قيمتها كل عام.\n\nووفق هذا التعريف يرى أن البيت الذي تسكنه ليس أصلًا كما يظن معظم الناس، لأنه يكلّفك كل شهر ولا يُدخل لك شيئًا. ويقول إن الطبقة الوسطى كثيرًا ما تزيد التزاماتها كلما زاد دخلها، كسيارة أغلى أو بيت أكبر، فيبقى الدخل الإضافي بلا أثر، بينما يستخدم الأغنياء الدخل الإضافي لشراء أصول تُدرّ مزيدًا من الدخل.\n\nالتعريف مثير للجدل بين خبراء المال، والكتاب نفسه تعرّض لانتقادات كثيرة، لكن الفكرة تدفعك إلى سؤال مفيد قبل أي شراء كبير: هل سيُدخل لي هذا مالًا أم سيُخرجه؟"},
{id:"graham-1",d:2,en:"The Intelligent Investor",a:"Benjamin Graham",t:"السيد سوق",
x:"يطلب جراهام أن تتخيّل أن لديك شريكًا في عمل تجاري اسمه السيد سوق، يأتيك كل يوم ويعرض عليك أن يشتري حصتك أو يبيعك حصته بسعر معيّن. لكنه متقلّب المزاج: في أيام الحماس يعرض أسعارًا مبالغًا فيها، وفي أيام الذعر يعرض أسعارًا زهيدة.\n\nالمستثمر الذكي لا يدع مزاج السيد سوق يحدد قيمة ما يملكه، بل يستفيد منه: يشتري حين يبيع الشريك بسعر أقل من القيمة الحقيقية، ويتجاهل عروضه في باقي الأيام. وهذه الفكرة كان وارن بافيت، تلميذ جراهام، يكررها كثيرًا: السوق في خدمتك، وليس مرشدك."},
{id:"thiel-1",d:3,en:"Zero to One",a:"Peter Thiel",t:"السؤال الذي يطرحه ثيل في المقابلات",
x:"يفرّق بيتر ثيل، أحد مؤسسي باي بال وأول مستثمر خارجي في فيسبوك، بين نوعين من التقدم: من واحد إلى ن، أي نسخ ما هو موجود وتوسيعه، كأن تفتح فرعًا جديدًا لمطعم ناجح، ومن صفر إلى واحد، أي صنع شيء جديد لم يكن موجودًا. ويرى أن الشركات العظيمة تأتي من النوع الثاني.\n\nلذلك يطرح في مقابلات التوظيف سؤالًا واحدًا: ما الحقيقة المهمة التي لا يتفق معك فيها إلا قليل من الناس؟ السؤال صعب لأن معظم الإجابات تكون آراء يتفق عليها الجميع، أو آراء غريبة لكنها غير مهمة.\n\nوإجابته هو مثال جيد: أغلب الناس يعتقدون أن المنافسة شيء صحي في الاقتصاد، بينما يرى ثيل أن المنافسة الشديدة تأكل أرباح الجميع، وأن الشركة الناجحة يجب أن تبحث عن احتكار سوق صغير ثم تتوسع. ويضرب مثلًا بجوجل، التي كانت تتفوق في البحث إلى درجة جعلتها شبه وحيدة في سوقها، بينما تتنافس مطاعم كثيرة في شارع واحد على هامش ربح ضئيل. جرّب أن تجيب عن سؤاله لنفسك."},
{id:"ries-1",d:3,en:"The Lean Startup",a:"Eric Ries",t:"اختبر الفكرة قبل أن تبنيها",
x:"يحكي إريك ريس قصة مؤسس متجر زابوس لبيع الأحذية عبر الإنترنت. قبل أن يبني مخازن أو يشتري بضاعة، ذهب إلى متاجر الأحذية في مدينته، وصوّر أحذيتها، ونشر الصور على موقع بسيط. وحين يطلب أحد زوجًا، كان يذهب إلى المتجر فيشتريه بنفسه ويرسله.\n\nلم يكن هذا نموذجًا مربحًا، لكنه أجاب عن السؤال الأهم: هل سيشتري الناس أحذية دون أن يجرّبوها؟ هذا ما يسميه ريس المنتج الأدنى القابل للتجربة: أصغر نسخة من فكرتك تكفي لتتعلم من العملاء الحقيقيين، ثم تبني وتقيس وتتعلم وتكرر، بدل أن تقضي سنوات في بناء شيء لا يريده أحد."},
{id:"collins-1",d:3,en:"Good to Great",a:"Jim Collins",t:"مفهوم القنفذ",
x:"درس جيم كولينز وفريقه شركات انتقلت من أداء متوسط إلى أداء استثنائي استمر سنوات، ووجد أنها تشترك في ما سمّاه مفهوم القنفذ. الاسم مأخوذ من حكاية الثعلب الذي يعرف أشياء كثيرة، والقنفذ الذي يعرف شيئًا واحدًا كبيرًا.\n\nالشركات العظيمة ركزت على تقاطع ثلاث دوائر: ما تستطيع أن تكون الأفضل في العالم فيه، وما تشعر بشغف حقيقي تجاهه، وما يحرّك محرّكها الاقتصادي. ومن أمثلته سلسلة صيدليات وولجرينز التي ركّزت على الصيدليات المريحة في أفضل المواقع، وقاست نجاحها بالربح من كل زيارة عميل. والفكرة تصلح للأفراد أيضًا عند اختيار مسارهم المهني."},
{id:"acemoglu-1",d:4,en:"Why Nations Fail",a:"Daron Acemoglu & James A. Robinson",t:"مدينة واحدة يقسمها سور",
x:"يبدأ الكتاب بمدينة نوجاليس التي يقسمها السور بين الولايات المتحدة والمكسيك. سكان الجانبين لهم الأصول نفسها والمناخ نفسه والطعام والموسيقى نفسها تقريبًا، ومع ذلك فإن سكان الجانب الأمريكي أعلى دخلًا وأطول عمرًا ويتمتعون بطرق ومدارس وأمن أفضل.\n\nومثال آخر أوضح: كوريا الشمالية وكوريا الجنوبية. كانتا شعبًا واحدًا بلغة وتاريخ واحد، ثم انقسمتا بعد الحرب العالمية الثانية. اليوم تُعد الجنوبية من أغنى دول العالم، بينما تعاني الشمالية من الفقر والمجاعات.\n\nالتفسير عند المؤلفين ليس الجغرافيا ولا الثقافة، بل المؤسسات. فالمؤسسات الشاملة تحمي الملكية وتطبق القانون على الجميع وتتيح الفرصة لعدد كبير من الناس، فتشجعهم على العمل والابتكار. أما المؤسسات الاستخراجية فتجعل الثروة والسلطة في يد قلة تستنزف الباقين، فلا يجد أحد سببًا ليستثمر أو يبتكر لأن ثمرة جهده قد تُؤخذ منه. ويرون أن هذا الفرق هو السبب الأعمق لغنى الأمم وفقرها."},
{id:"freakonomics-1",d:4,en:"Freakonomics",a:"Steven D. Levitt & Stephen J. Dubner",t:"عندما يبيع السمسار بيته",
x:"يدرس ليفيت ودابنر سلوك الناس من خلال الحوافز. ومن أشهر أمثلتهما سماسرة العقارات: حلّلا بيانات آلاف صفقات البيع، فوجدا أن السمسار حين يبيع بيته الخاص يبقيه معروضًا في السوق مدة أطول بنحو عشرة أيام، ويبيعه بسعر أعلى بنحو ثلاثة في المئة، مقارنة بالبيوت المماثلة التي يبيعها لعملائه.\n\nالسبب أن عمولة السمسار من الزيادة الصغيرة في سعر بيتك قليلة، فلا تستحق عنده الانتظار، بينما تلك الزيادة كلها من حقك. الدرس: عندما تسمع نصيحة من خبير، اسأل أولًا ما الحافز الذي يحرّكه، وهل مصلحته متطابقة مع مصلحتك."},
{id:"nudge-1",d:4,en:"Nudge",a:"Richard H. Thaler & Cass R. Sunstein",t:"ذبابة صغيرة غيّرت السلوك",
x:"في دورات مياه الرجال بمطار أمستردام، رُسمت صورة ذبابة صغيرة داخل كل مبولة. النتيجة كانت انخفاض الانسكاب على الأرض بنحو ثمانين في المئة، لأن الناس يحبون التصويب على هدف. هذا مثال على ما يسميه المؤلفان الوكزة: تغيير صغير في طريقة عرض الخيارات يغيّر السلوك دون منع أو إجبار.\n\nومن أقوى أشكال الوكزة الخيار الافتراضي؛ فالدول التي تجعل التبرع بالأعضاء هو الأصل، ومن لا يريده عليه أن يلغيه، تحقق نسب تبرع أعلى بكثير من الدول التي تطلب من الناس أن يسجلوا بأنفسهم. ويمكنك استخدام الفكرة نفسها مع نفسك: ضع الخيار الصحي أمامك والخيار السيئ بعيدًا."},
{id:"harari-1",d:5,en:"Sapiens: A Brief History of Humankind",a:"Yuval Noah Harari",t:"قوة القصص المشتركة",
x:"لماذا سيطر الإنسان العاقل على الأرض رغم أن الشمبانزي أقوى منه جسديًا؟ يجيب هراري بأن قوتنا في قدرتنا على التعاون بأعداد هائلة مع غرباء لا نعرفهم. والسر في ذلك أننا نؤمن معًا بقصص لا وجود لها إلا في خيالنا المشترك: الأموال والدول والقوانين والشركات.\n\nويضرب مثالًا بشركة بيجو: لا يمكنك أن تلمس الشركة نفسها؛ فلو احترقت مصانعها لبقيت قائمة قانونيًا، ولو أصدرت المحكمة قرارًا بحلّها لانتهت رغم بقاء المصانع. والورقة النقدية أيضًا لا قيمة لها في ذاتها، وقيمتها تأتي من أن الملايين يصدّقون القصة نفسها."},
{id:"diamond-1",d:5,en:"Guns, Germs, and Steel",a:"Jared Diamond",t:"لماذا كانت الجغرافيا قدرًا",
x:"سأل رجل من غينيا الجديدة اسمه يالي جاريد دايموند: لماذا يملك البيض كل هذه البضائع، ولا نملك نحن إلا القليل؟ استغرق دايموند كتابًا كاملًا ليجيب، وكان جوابه أن الفرق ليس في ذكاء الشعوب بل في الجغرافيا.\n\nفقد امتلكت منطقة أوراسيا نباتات وحيوانات أكثر قابلية للزراعة والتدجين، مثل القمح والأبقار والخيول. كما أن امتدادها من الشرق إلى الغرب جعل المحاصيل تنتقل بسهولة بين مناطق على خط عرض واحد ومناخ متشابه، بينما تمتد الأمريكتان وأفريقيا من الشمال إلى الجنوب، فتتغير المناخات وتتعطل الزراعة.\n\nومن الزراعة جاء فائض الغذاء، ثم المدن والكتابة والحِرف والجيوش. ومن العيش قرب الحيوانات المدجّنة جاءت أمراض مثل الجدري، فاكتسب الأوروبيون مناعة جزئية منها عبر قرون.\n\nويظهر أثر ذلك في مشهد يرويه دايموند: عام ألف وخمسمئة واثنين وثلاثين، واجه القائد الإسباني بيزارو ومعه أقل من مئتي رجل جيش إمبراطور الإنكا أتاهوالبا بعشرات الآلاف، وأسره. ساعدته الخيول والفولاذ والبنادق، لكن الجدري كان قد سبقه وقتل أعدادًا هائلة من السكان وأضعف الإمبراطورية من الداخل."},
{id:"frankopan-1",d:5,en:"The Silk Roads",a:"Peter Frankopan",t:"أين كان مركز العالم؟",
x:"تعلمنا في المدارس أن التاريخ يدور حول أوروبا: اليونان ثم روما ثم النهضة الأوروبية. يطلب فرانكوبان أن ننظر إلى الخريطة بطريقة أخرى. فلآلاف السنين كان مركز العالم في المنطقة الواقعة بين شرق البحر المتوسط ووسط آسيا، أي في بلاد فارس وبغداد ودمشق وسمرقند.\n\nهناك التقت طرق التجارة بين الصين والهند وأوروبا، وانتقلت عبرها البضائع كالحرير والتوابل، ومعها الأديان والأفكار والعلوم وحتى الأوبئة. وكانت أوروبا لفترات طويلة طرفًا بعيدًا عن هذا المركز. ويرى المؤلف أن هذه المنطقة تعود اليوم لتكون محور الاهتمام العالمي بسبب الطاقة والتجارة."},
{id:"hawking-1",d:6,en:"A Brief History of Time",a:"Stephen Hawking",t:"تنظر إلى الماضي كل ليلة",
x:"يشرح هوكينج أن الضوء، رغم سرعته الهائلة، يحتاج إلى وقت ليصل إلينا. ضوء الشمس يستغرق نحو ثماني دقائق، فنحن نرى الشمس كما كانت قبل ثماني دقائق لا كما هي الآن. أما ضوء النجوم البعيدة فقد يستغرق آلاف أو ملايين السنين، فبعض النجوم التي تراها الليلة ربما لم تعد موجودة أصلًا.\n\nومن هنا جاءت إحدى أهم الأفكار في الكتاب: عندما نرصد المجرات البعيدة نرى ماضي الكون. وقد كشف هذا الرصد أن المجرات تبتعد عن بعضها، أي أن الكون يتمدد، ما يعني أنه كان في الماضي أصغر وأكثف، وهو ما قاد إلى نظرية الانفجار العظيم."},
{id:"dawkins-1",d:6,en:"The Selfish Gene",a:"Richard Dawkins",t:"أنت آلة بقاء",
x:"يقترح دوكينز أن ننظر إلى التطور من زاوية الجين لا من زاوية الفرد. فالجينات هي ما ينتقل عبر الأجيال، أما أجسامنا فهي في نظره آلات بقاء مؤقتة تبنيها الجينات لتنقل نسخًا منها إلى المستقبل. وكلمة الأناني هنا مجاز، فالجين لا يملك نوايا، لكن الجينات التي تنجح في البقاء هي التي تنتشر.\n\nوهذه الفكرة تفسّر لغزًا قديمًا: لماذا يضحّي حيوان من أجل أقاربه؟ لأن أقاربه يحملون نسخًا كثيرة من جيناته نفسها. وتُنسب إلى عالم الأحياء هالدين عبارة ساخرة في هذا المعنى: مستعد أن أضحّي بحياتي من أجل أخوين أو ثمانية من أبناء العمومة."},
{id:"mukherjee-1",d:6,en:"The Gene: An Intimate History",a:"Siddhartha Mukherjee",t:"الراهب الذي سبق عصره",
x:"في حديقة دير في مدينة برنو بأوروبا الوسطى، زرع راهب اسمه جريجور مندل آلاف نباتات البازلاء على مدى سنوات، وسجّل بدقة لون البذور وشكلها وطول السيقان عبر الأجيال. اكتشف أن الصفات تنتقل في وحدات منفصلة لا تختلط، وأن بعضها يختفي في جيل ثم يعود في الجيل التالي بنسب ثابتة.\n\nنشر نتائجه عام ألف وثمانمئة وستة وستين، لكن أحدًا تقريبًا لم يفهم قيمتها، فبقيت مهملة نحو أربعة وثلاثين عامًا حتى أعاد علماء اكتشافها عام ألف وتسعمئة. ويحكي موكرجي كيف صارت تلك الوحدات التي رآها مندل في البازلاء هي ما نسميه اليوم الجينات."},
{id:"aurelius-1",d:7,en:"Meditations",a:"Marcus Aurelius",t:"دفتر إمبراطور لنفسه",
x:"كان ماركوس أوريليوس إمبراطورًا لروما، أقوى رجل في عصره، ومع ذلك كان يكتب ملاحظات لنفسه لم يقصد نشرها أبدًا، يذكّر فيها نفسه بمبادئ الفلسفة الرواقية. ومن أشهر هذه التذكيرات تمرين صباحي: أن يقول لنفسه في أول اليوم إنه سيقابل اليوم أناسًا متطفلين وجاحدين ومتكبرين، لكن ذلك لن يضرّه، لأنهم يتصرفون عن جهل، ولأن أحدًا لا يستطيع أن يجبره على أن يصبح سيئًا مثلهم.\n\nالفكرة أن تستعد ذهنيًا لما لا تتحكم فيه، وأن تركز على ما تتحكم فيه، وهو حكمك وتصرفك. وما زال هذا الدفتر الخاص يُقرأ بعد نحو ألفي عام."},
{id:"seneca-1",d:7,en:"Letters from a Stoic",a:"Seneca",t:"تدرّب على ما تخافه",
x:"في إحدى رسائله إلى صديقه لوسيليوس، يقترح الفيلسوف الروماني سينيكا تمرينًا غريبًا: خصّص بضعة أيام تعيش فيها بأقل القليل، طعام بسيط وملابس خشنة، ثم اسأل نفسك: هل هذا هو ما كنت أخاف منه؟\n\nكان سينيكا ثريًا جدًا، ولم يكن يدعو إلى الفقر، بل إلى التحرر من الخوف منه. فحين تجرب أسوأ ما تخشاه في ظروف آمنة، تكتشف أنه أخف مما تتخيل، فيقل قلقك على ما تملك، وتستمتع به أكثر لأنك لم تعد عبدًا له. ويمكن تطبيق الفكرة اليوم بصور كثيرة: يوم دون هاتف، أو أسبوع بميزانية صغيرة جدًا، لترى أنك تستطيع الاستغناء."},
{id:"durant-1",d:7,en:"The Story of Philosophy",a:"Will Durant",t:"الجملة التي نسبها الجميع لأرسطو",
x:"تنتشر على الإنترنت عبارة منسوبة إلى أرسطو معناها: نحن ما نفعله مرارًا وتكرارًا، فالتميّز ليس فعلًا بل عادة. والحقيقة أن أرسطو لم يكتبها بهذه الصياغة، بل كتبها المؤرخ ول ديورانت في كتابه قصة الفلسفة وهو يلخّص أفكار أرسطو عن الفضيلة.\n\nلكن المعنى أرسطي فعلًا: كان أرسطو يرى أن الفضيلة لا تولد مع الإنسان، بل تُكتسب بالممارسة، فنصبح شجعانًا بأن نفعل أفعالًا شجاعة، ونصبح عادلين بأن نفعل أفعالًا عادلة. وهذا ما يميّز كتاب ديورانت: أنه يقدّم أفكار الفلاسفة الكبار بلغة واضحة ومشوّقة جعلت الفلسفة في متناول القارئ العادي."},
{id:"walker-1",d:8,en:"Why We Sleep",a:"Matthew Walker",t:"ساعة نوم واحدة وقلبك",
x:"يذكر عالم الأعصاب ماثيو ووكر تجربة طبيعية تحدث مرتين كل عام في الدول التي تطبق التوقيت الصيفي. في الربيع، حين تُقدَّم الساعة ويخسر الناس ساعة من نومهم، لوحظت زيادة في النوبات القلبية في اليوم التالي بنحو أربعة وعشرين في المئة. وفي الخريف، حين يكسب الناس ساعة نوم إضافية، لوحظ انخفاض مقارب.\n\nويستخدم ووكر هذا المثال ليوضح مدى حساسية الجسم لقلة النوم، حتى لو كانت ساعة واحدة. ويرى أن النوم ليس وقتًا ضائعًا، بل عملية نشطة يصلح فيها الجسم نفسه وينظّم فيها الدماغ ذكرياته، وأن النوم المنتظم من أقوى ما يمكنك فعله لصحتك."},
{id:"attia-1",d:8,en:"Outlive",a:"Peter Attia",t:"الفرسان الأربعة",
x:"يرى الطبيب بيتر عطية أن معظم الناس في الدول المتقدمة لا يموتون فجأة، بل بسبب أحد أربعة أمراض مزمنة يسميها الفرسان الأربعة: أمراض القلب والأوعية، والسرطان، وأمراض تنكّس الدماغ مثل ألزهايمر، والأمراض الأيضية مثل السكري من النوع الثاني. وهذه الأمراض تتطور بصمت على مدى عقود قبل أن تظهر أعراضها، لذلك يدعو إلى طب وقائي يبدأ مبكرًا بدل انتظار المرض.\n\nوأقوى أداة في رأيه ليست دواءً، بل التمرين: فاللياقة القلبية التنفسية وقوة العضلات من أقوى المؤشرات على طول العمر وجودته. ويطلب أن تسأل نفسك: ماذا أريد أن أستطيع فعله وأنا في الثمانين؟ ثم تتدرّب لذلك الآن."},
{id:"nestor-1",d:8,en:"Breath",a:"James Nestor",t:"أغلق فمك",
x:"أجرى الصحفي جيمس نستور تجربة على نفسه بالتعاون مع باحثين في جامعة ستانفورد: سدّ أنفه تمامًا لمدة عشرة أيام، فاضطر إلى التنفس من فمه فقط. خلال تلك الأيام ارتفع ضغط دمه، وزاد شخيره بشكل كبير، وساءت جودة نومه. وحين عاد للتنفس من أنفه تحسّنت هذه المؤشرات.\n\nيشرح نستور أن الأنف ليس مجرد فتحة للهواء، بل يرشّحه ويدفّئه ويرطّبه قبل وصوله إلى الرئتين. ويذكر أن التنفس البطيء، بنحو خمس ثوانٍ ونصف للشهيق ومثلها للزفير، يساعد على تهدئة الجسم. جرّب الآن أن تتنفس من أنفك ببطء لدقيقة واحدة ولاحظ الفرق."},
{id:"carnegie-1",d:9,en:"How to Win Friends and Influence People",a:"Dale Carnegie",t:"أحب صوت إلى أذن الإنسان",
x:"من أبسط نصائح ديل كارنيجي وأقواها: تذكّر أسماء الناس. فاسم الإنسان عنده هو أحب صوت إلى أذنه في أي لغة. حين تنادي شخصًا قابلته مرة واحدة باسمه، يشعر بأنه مهم بالنسبة لك، وحين تنساه أو تخطئ فيه، يشعر بالعكس.\n\nويحكي كارنيجي عن السياسي الأمريكي جيم فارلي، الذي ترك المدرسة صغيرًا، لكنه كان يقول إنه يستطيع أن ينادي نحو خمسين ألف شخص بأسمائهم الأولى. وقد ساعدته هذه العادة في إدارة الحملة التي أوصلت فرانكلين روزفلت إلى رئاسة الولايات المتحدة.\n\nوطريقة الحفظ بسيطة: كرّر الاسم في أثناء الحديث، واسأل عن طريقة كتابته إن كان غريبًا، واربطه بصورة أو معلومة عن صاحبه. جرّب في أول لقاء قادم أن تستخدم اسم محدّثك مرتين."},
{id:"voss-1",d:9,en:"Never Split the Difference",a:"Chris Voss",t:"سحر تكرار آخر كلمات",
x:"كان كريس فوس كبير مفاوضي مكتب التحقيقات الفيدرالي الأمريكي في قضايا الخطف الدولية، ومن أبسط تقنياته ما يسميه المرآة: أن تكرر آخر كلمة إلى ثلاث كلمات قالها الطرف الآخر، بنبرة استفهام هادئة، ثم تصمت.\n\nمثال: يقول لك مديرك: نحتاج إلى نسختين من هذا التقرير. فتقول: نسختين؟ غالبًا سيشرح: نعم، واحدة للعميل وواحدة للإدارة، لأن العميل يريدها بصيغة مختلفة. فتحصل على معلومة كانت ستغيب عنك، دون أن تبدو معترضًا. السبب أن البشر يشعرون بالارتياح مع من يشبهونهم ويصغون إليهم، فيفتحون أكثر.\n\nوتقنية أخرى يسميها التسمية: أن تصف شعور الطرف الآخر بصوت مسموع، كأن تقول: يبدو أنك قلق من الموعد. هذه العبارة تخفف التوتر لأن الشخص يشعر بأنه مفهوم. ويرى فوس أن التفاوض ليس معركة منطق، بل فهم لمشاعر الطرف الآخر، وهو ما يسميه التعاطف التكتيكي. والتقنيتان تصلحان في العمل والبيت على حد سواء."},
{id:"rosenberg-1",d:9,en:"Nonviolent Communication",a:"Marshall B. Rosenberg",t:"أربع خطوات للكلام دون صدام",
x:"يقترح مارشال روزنبرج طريقة للتعبير عن نفسك دون أن يشعر الآخر بالهجوم، تتكون من أربع خطوات:\n\nالأولى: ملاحظة ما حدث فعلًا دون حكم. بدل أن تقول: أنت مستهتر، تقول: تأخرت ثلاث مرات هذا الأسبوع.\nالثانية: التعبير عن شعورك، كأن تقول: وأشعر بالقلق والضيق.\nالثالثة: ذكر الحاجة التي وراء هذا الشعور: لأنني أحتاج إلى أن أعتمد على مواعيدنا لأرتب يومي.\nالرابعة: طلب واضح ومحدد وقابل للتنفيذ: هل يمكنك أن ترسل لي رسالة حين تعرف أنك ستتأخر؟\n\nقارن الجملتين الكاملتين. الأولى: أنت دائمًا متأخر ولا تحترم وقت أحد. والثانية: تأخرت ثلاث مرات هذا الأسبوع، وأشعر بالضيق لأنني أحتاج إلى أن أرتب يومي، فهل يمكنك أن تخبرني مسبقًا حين تتأخر؟ الأولى تدفع الآخر إلى الدفاع عن نفسه أو الهجوم المضاد، والثانية تفتح بابًا للحل.\n\nالفكرة عند روزنبرج أن الأحكام والاتهامات تجعل الآخر يسمع لومًا فقط، بينما الملاحظات والحاجات تجعله يفهم ما يهمك فعلًا."},
{id:"isaacson-1",d:10,en:"Steve Jobs",a:"Walter Isaacson",t:"درس الخط الذي صنع الماك",
x:"ترك ستيف جوبز الدراسة الرسمية في كلية ريد بعد فصل دراسي واحد، لكنه بقي فيها فترة يحضر ما يحبه من محاضرات دون تسجيل. ومن بين ما حضره دروس في فن الخط، تعلّم فيها أنواع الحروف والمسافات بينها وجمال التصميم الطباعي. لم يكن لهذا أي فائدة عملية في حياته وقتها.\n\nلكن بعد نحو عشر سنوات، حين صمّم جهاز ماكنتوش، وضع فيه كل ما تعلمه، فكان من أوائل الحواسيب الشخصية التي قدّمت خطوطًا متعددة وجميلة. ويحكي إيزاكسون كيف كان جوبز يرى أن الإبداع يأتي من الجمع بين التقنية والفنون، وأنك لا تستطيع ربط النقاط إلا حين تنظر إلى الوراء."},
{id:"mandela-1",d:10,en:"Long Walk to Freedom",a:"Nelson Mandela",t:"تعلّم لغة سجّانه",
x:"قضى نيلسون مانديلا سبعة وعشرين عامًا في السجن، معظمها في جزيرة روبن. وخلال هذه السنوات فعل شيئًا استغربه بعض رفاقه: تعلّم اللغة الأفريكانية، لغة الأقلية البيضاء الحاكمة وسجّانيه، وقرأ تاريخهم وأدبهم. كان هدفه أن يفهم خصمه من الداخل؛ فالحديث مع الإنسان بلغته يصل إلى قلبه، لا إلى عقله فقط.\n\nوقد ساعده ذلك لاحقًا في التفاوض على إنهاء نظام الفصل العنصري، وفي طمأنة البيض بأن جنوب أفريقيا الجديدة لهم أيضًا. وحين خرج من السجن وصار رئيسًا، اختار المصالحة بدل الانتقام، وهو ما جعل انتقال البلاد أكثر سلمًا مما توقعه كثيرون."},
{id:"knight-1",d:10,en:"Shoe Dog",a:"Phil Knight",t:"شعار بخمسة وثلاثين دولارًا",
x:"بدأ فيل نايت مشروعه بقرض قيمته خمسون دولارًا من والده، يستورد به أحذية رياضية من شركة يابانية ويبيعها من صندوق سيارته في مضامير الجري. ويحكي في مذكراته أن السنوات الأولى كانت سلسلة من الأزمات المالية، وأن البنوك رفضته مرارًا.\n\nوحين احتاجت شركته إلى شعار، طلب من طالبة تصميم في جامعة بورتلاند اسمها كارولين ديفيدسون أن تصمم واحدًا، ودفع لها خمسة وثلاثين دولارًا. لم يكن معجبًا بالتصميم كثيرًا، لكنه قال إنه ربما يحبه مع الوقت. أما اسم نايكي، إلهة النصر عند اليونان، فجاء من أول موظف لديه، وقال إنه رآه في حلم."},
{id:"duhigg-1",d:0,en:"The Power of Habit",a:"Charles Duhigg",t:"لماذا فشل معطّر الهواء في البداية؟",
x:"يشرح دوهيج أن كل عادة تتكون من حلقة من ثلاثة أجزاء: إشارة تطلق السلوك، ثم الروتين نفسه، ثم مكافأة تجعل الدماغ يريد تكراره.\n\nومن أمثلته منتج فبريز الذي أطلقته شركة بروكتر آند جامبل في التسعينيات لإزالة الروائح. كان المنتج يعمل جيدًا، لكن المبيعات جاءت مخيبة. اكتشف الباحثون السبب حين زاروا امرأة تعيش مع تسع قطط، وكان بيتها برائحة قوية جدًا، بينما هي لا تشمّها أصلًا. فالناس يعتادون روائح بيوتهم، فلا توجد إشارة تذكّرهم باستخدام المنتج.\n\nفغيّرت الشركة الفكرة: أضافت عطرًا لطيفًا، وقدّمت المنتج على أنه اللمسة الأخيرة بعد التنظيف، كمكافأة صغيرة على إنهاء المهمة. عندها ارتبط المنتج بعادة موجودة أصلًا، فارتفعت المبيعات وأصبح من أنجح منتجات الشركة. الدرس: لكي تبني عادة جديدة، اربطها بإشارة واضحة ومكافأة تشعر بها."},
{id:"cain-1",d:0,en:"Quiet",a:"Susan Cain",t:"خرافة العصف الذهني الجماعي",
x:"تقول سوزان كين إن ما بين ثلث ونصف الناس انطوائيون، ومع ذلك تُصمَّم المدارس وأماكن العمل كأن الجميع اجتماعيون يحبون العمل في مجموعات.\n\nومن أمثلتها العصف الذهني الجماعي، أي أن يجتمع فريق ويطرح الأفكار بصوت عالٍ. انتشرت هذه الطريقة في الشركات لعقود، لكن أبحاثًا كثيرة وجدت أن الأشخاص أنفسهم ينتجون أفكارًا أكثر وأفضل إذا عمل كل منهم بمفرده ثم جُمعت الأفكار. والسبب أن المجموعة تميل إلى اتباع أول رأي يُطرح، وأن بعض الناس يسكتون خوفًا من الحكم عليهم، وأن الأعلى صوتًا ليس بالضرورة صاحب الفكرة الأفضل.\n\nلا تقول كين إن العمل الجماعي سيئ، بل إن التفكير العميق يحتاج غالبًا إلى هدوء وعزلة، وإن الانطوائية ليست عيبًا يجب إصلاحه، بل طريقة مختلفة في استخدام الطاقة."},
{id:"dweck-1",d:0,en:"Mindset",a:"Carol S. Dweck",t:"لا تمدح ذكاء طفلك",
x:"تفرّق عالمة النفس كارول دويك بين عقليتين: العقلية الثابتة التي ترى أن الذكاء والموهبة صفات ثابتة تولد معك، والعقلية النامية التي ترى أن القدرات تُبنى بالجهد والتعلم.\n\nوفي إحدى تجاربها أعطت أطفالًا في المدرسة مسائل سهلة، ثم مدحت نصفهم على ذكائهم، فقالت لهم: أنت ذكي جدًا، ومدحت النصف الآخر على جهدهم، فقالت: لقد عملت بجد. بعد ذلك خُيّر الأطفال بين مهمة سهلة ومهمة صعبة يتعلمون منها. أغلب من مُدحوا على ذكائهم اختاروا المهمة السهلة، كي لا يخسروا لقب الذكي، بينما اختار أغلب من مُدحوا على جهدهم المهمة الصعبة. وحين واجه الجميع لاحقًا مسائل صعبة، تراجع أداء المجموعة الأولى، وتحسّن أداء الثانية.\n\nالدرس: امدح الجهد والطريقة، لا الموهبة، مع الآخرين ومع نفسك."},
{id:"goggins-1",d:1,en:"Can't Hurt Me",a:"David Goggins",t:"قاعدة الأربعين في المئة",
x:"عاش ديفيد جوجينز طفولة قاسية، وكان في شبابه يعاني من زيادة الوزن ويعمل في وظيفة لا يحبها. ثم قرر أن ينضم إلى قوات النخبة البحرية الأمريكية، فخسر نحو ثمانية وأربعين كيلوجرامًا في أقل من ثلاثة أشهر ليتأهل للاختبارات، وصار لاحقًا من أشهر عدّائي المسافات الطويلة جدًا.\n\nومن أشهر أفكاره قاعدة الأربعين في المئة: عندما يقول لك عقلك إنك انتهيت ولا تستطيع الاستمرار، تكون في الحقيقة قد استهلكت نحو أربعين في المئة فقط مما تستطيعه. فالعقل يرسل إشارة التوقف مبكرًا ليحميك من الألم، لا لأن طاقتك نفدت فعلًا.\n\nالنسبة نفسها ليست رقمًا علميًا دقيقًا، بل طريقة للتفكير. والفكرة أنك حين تشعر بالرغبة في الاستسلام، يمكنك أن تسأل نفسك: هل هذا حدّي الحقيقي، أم مجرد أول إشارة من عقلي؟"},
{id:"manson-1",d:1,en:"The Subtle Art of Not Giving a F*ck",a:"Mark Manson",t:"أي ألم تريد؟",
x:"يرى مارك مانسون أن السؤال المعتاد: ماذا تريد في حياتك؟ سؤال سهل لا يفيد كثيرًا، لأن الجميع يريد الشيء نفسه تقريبًا: النجاح والمال والصحة والحب. السؤال الأهم في رأيه هو: ما الألم الذي أنت مستعد لتحمّله؟\n\nفالجميع يريد جسمًا رياضيًا، لكن قليلين يريدون ألم التمرين والالتزام بالأكل. والجميع يريد شركة ناجحة، لكن قليلين مستعدون لسنوات من القلق والفشل والعمل الطويل. ويحكي مانسون أنه كان في شبابه يحلم بأن يصبح نجم موسيقى روك، لكنه لم يحب أبدًا ساعات التدريب ولا البحث عن فرقة ولا عروض الأماكن الصغيرة. فاكتشف أنه كان يحب الصورة النهائية، لا الطريق إليها.\n\nالدرس: نجاحك لا يتحدد بما تحب أن تحصل عليه، بل بالصعوبات التي تستمتع بالكفاح فيها. اختر أهدافًا تحب طريقها، لا نهايتها فقط."},
{id:"mckeown-1",d:1,en:"Essentialism",a:"Greg McKeown",t:"قاعدة التسعين",
x:"يرى جريج ماكيون أن كثيرًا من الناس مشغولون جدًا لكنهم لا يتقدمون، لأنهم يقولون نعم لكل شيء، فيوزعون جهدهم على أشياء كثيرة ولا يتقدمون في أي منها.\n\nوللخروج من هذا الفخ يقترح أداة بسيطة يسميها قاعدة التسعين في المئة. عندما تقيّم أي فرصة، كوظيفة أو مشروع أو دعوة أو التزام جديد، أعطها درجة من مئة بناءً على أهم معيار عندك. إذا كانت الدرجة أقل من تسعين، فاعتبرها صفرًا وارفضها. هذا يحميك من المنطقة الرمادية، أي الفرص التي تبدو جيدة إلى حد ما، فتقبلها، ثم تكتشف أنها أكلت وقتك ولم تترك مكانًا للفرص الممتازة حين تأتي.\n\nالفكرة الأساسية في الكتاب أن قول لا بأدب ووضوح مهارة، وأن التركيز على القليل المهم أفضل من الإنجاز السطحي في أشياء كثيرة."},
{id:"stanley-1",d:2,en:"The Millionaire Next Door",a:"Thomas J. Stanley & William D. Danko",t:"المليونير الذي لا تلاحظه",
x:"في التسعينيات درس الباحثان توماس ستانلي وويليام دانكو أصحاب الثروات في الولايات المتحدة، وتوقّعا أن يجدوهم في الأحياء الفاخرة والسيارات الفارهة. لكن النتيجة كانت مختلفة: كثير من المليونيرات الحقيقيين يعيشون في بيوت عادية، ويقودون سيارات مستعملة، ويشترون ملابس عادية، ويملكون أعمالًا غير لافتة مثل مقاولات أو تجارة بسيطة.\n\nفي المقابل وجدا أن كثيرًا من أصحاب الدخل المرتفع الذين يبدون أثرياء، بسياراتهم وبيوتهم الفخمة، لا يملكون ثروة حقيقية، لأنهم ينفقون كل ما يكسبونه تقريبًا. ويستخدم المؤلفان تعبيرًا من تكساس يصف هؤلاء: قبعة كبيرة بلا ماشية، أي مظهر رجل المزرعة دون المزرعة.\n\nالدرس: الثروة ليست ما تكسبه، بل ما تحتفظ به. ومظاهر الثراء غالبًا هي بالضبط ما يمنع الناس من أن يصبحوا أثرياء."},
{id:"sethi-1",d:2,en:"I Will Teach You to Be Rich",a:"Ramit Sethi",t:"أنفق بسخاء على ما تحبه فقط",
x:"يرفض راميت سيثي نصائح التوفير المعتادة التي تطلب منك أن تحرم نفسك من كل متعة صغيرة، كفنجان القهوة اليومي. ويرى أن هذا الحرمان لا يستمر، وأن المبالغ الصغيرة ليست أصل المشكلة.\n\nبدلًا من ذلك يقترح ما يسميه الإنفاق الواعي: أن تنفق بسخاء على الأشياء التي تحبها فعلًا، وأن تقطع بلا رحمة الإنفاق على الأشياء التي لا تهمك. فإذا كنت تحب السفر، فخصص له ميزانية كبيرة دون شعور بالذنب، لكن اسأل نفسك لماذا تدفع لاشتراكات لا تستخدمها، أو لسيارة أغلى مما تحتاجه.\n\nويقترح أن تبدأ بالأشياء الكبيرة، كالادخار التلقائي من الراتب في يوم استلامه، قبل أن تفكر في المصروفات الصغيرة. فإذا ذهب جزء من دخلك تلقائيًا إلى الادخار والاستثمار، يمكنك أن تنفق الباقي براحة. الفكرة أن المال وسيلة لتعيش الحياة التي تريدها، لا مصدر دائم للقلق."},
{id:"clason-1",d:2,en:"The Richest Man in Babylon",a:"George S. Clason",t:"جزء مما تكسبه لك",
x:"كتب جورج كلاسون هذا الكتاب في عشرينيات القرن العشرين على شكل حكايات تدور في مدينة بابل القديمة، ليشرح قواعد مالية بسيطة. وأشهر هذه الحكايات قصة أركاد، أغنى رجل في بابل، الذي كان كاتبًا فقيرًا ينقش الألواح، حين سأل رجلًا غنيًا يُقرض المال عن سرّ ثروته.\n\nكان الجواب: جزء مما تكسبه هو لك لتحتفظ به. أي أن تدفع لنفسك أولًا، قبل أن تدفع للخباز والخياط وكل من تشتري منهم. والقاعدة في الكتاب أن تحتفظ بعُشر دخلك على الأقل، مهما كان الدخل صغيرًا. ثم لا تكتفي بتخزين هذا المال، بل تجعله يعمل لك، كأنك ترسل عبيدًا من الذهب يعودون إليك بمزيد من الذهب.\n\nالأمثلة قديمة، لكن الفكرة ما زالت أساس التخطيط المالي اليوم: ادّخر نسبة ثابتة من كل دخل فور استلامه، واستثمرها، ولا تنتظر أن يتبقى شيء في آخر الشهر."},
{id:"horowitz-1",d:3,en:"The Hard Thing About Hard Things",a:"Ben Horowitz",t:"مدير السلم ومدير الحرب",
x:"بن هورويتز رائد أعمال ومستثمر، أدار شركة تقنية مرّت بأزمات كادت تقضي عليها. ومن أفكاره في الكتاب التفريق بين نوعين من المديرين: مدير وقت السلم ومدير وقت الحرب.\n\nفي وقت السلم تكون الشركة متفوقة في سوق ينمو، فيكون دور المدير توسيع الفرص، وتشجيع الإبداع، وبناء ثقافة يرتاح فيها الموظفون. أما في وقت الحرب، حين تواجه الشركة خطرًا يهدد وجودها، كمنافس قوي أو أزمة مالية، فيحتاج المدير إلى قرارات سريعة وحاسمة، وإلى تركيز صارم على هدف واحد، حتى لو كانت هذه القرارات مؤلمة أو غير شعبية.\n\nومن أمثلته آندي جروف في إنتل، الذي قرر في الثمانينيات الخروج من صناعة شرائح الذاكرة، وهي أصل الشركة، والتركيز على المعالجات، لأن المنافسين اليابانيين كانوا يتفوقون فيها. القرار كان مؤلمًا، لكنه أنقذ الشركة. والصعوبة الحقيقية أن تعرف في أي وقت أنت."},
{id:"kim-1",d:3,en:"Blue Ocean Strategy",a:"W. Chan Kim & Renée Mauborgne",t:"سيرك بلا حيوانات",
x:"يقسم المؤلفان الأسواق إلى نوعين: محيطات حمراء، وهي أسواق مزدحمة يتنافس فيها الجميع على العملاء أنفسهم حتى يصبح لون الماء أحمر من شدة المعركة، ومحيطات زرقاء، وهي مساحات جديدة لا منافسة فيها لأن أحدًا لم يدخلها بعد.\n\nومثالهم الأشهر سيرك دو سوليه الكندي. كانت صناعة السيرك في تراجع: الجمهور يقلّ، وتكاليف الحيوانات والنجوم ترتفع، وانتقادات معاملة الحيوانات تزيد. فبدل أن ينافس السيركات الأخرى في الأشياء نفسها، ألغى سيرك دو سوليه الحيوانات ونجوم السيرك المكلفين، وأضاف ما تتميز به المسارح: قصة وموسيقى وإضاءة وتصميم فني. فصار عرضًا لا هو سيرك تقليدي ولا مسرح، وجذب جمهورًا من الكبار مستعدًا لدفع أسعار أعلى.\n\nالدرس: بدل أن تسأل كيف أتفوق على منافسيّ، اسأل ماذا يمكنني أن ألغي أو أضيف لأخلق شيئًا لا يقارَن بهم أصلًا."},
{id:"christensen-1",d:3,en:"The Innovator's Dilemma",a:"Clayton M. Christensen",t:"لماذا تسقط الشركات الناجحة؟",
x:"لاحظ كلايتون كريستنسن، الأستاذ في جامعة هارفارد، أن شركات كبيرة ومُدارة جيدًا تسقط أحيانًا أمام شركات صغيرة، والمفارقة أنها تسقط لأنها تفعل ما يبدو صحيحًا تمامًا: تستمع لأفضل عملائها، وتطور منتجاتها الأغلى والأكثر ربحًا.\n\nومن أمثلته صناعة الحديد. كانت مصانع الحديد الكبيرة تنتج أنواعًا كثيرة، ثم ظهرت مصانع صغيرة تعيد صهر الخردة، وكانت جودتها في البداية ضعيفة، فلم تنتج إلا قضبان التسليح الرخيصة، وهو أقل الأسواق ربحًا. فرحت المصانع الكبيرة بترك هذا السوق لها. لكن المصانع الصغيرة تحسنت مع الوقت، وصعدت إلى سوق بعد آخر، والمصانع الكبيرة تتراجع في كل مرة نحو الأسواق الأعلى ربحًا، حتى لم يبقَ لها مكان.\n\nهذا ما يسميه الابتكار الهدّام: منتج يبدأ رخيصًا وأضعف، فيتجاهله الكبار، ثم يتحسن حتى يأخذ السوق كله."},
{id:"piketty-1",d:4,en:"Capital in the Twenty-First Century",a:"Thomas Piketty",t:"المعادلة التي شغلت العالم",
x:"جمع الاقتصادي الفرنسي توماس بيكيتي بيانات عن الثروة والدخل في دول كثيرة على مدى أكثر من قرنين، وخرج بفكرة يلخصها في معادلة قصيرة: r أكبر من g.\n\nالحرف الأول يعني العائد على رأس المال، أي ما تكسبه الأموال والعقارات والأسهم لأصحابها. والحرف الثاني يعني نمو الاقتصاد ككل، وبالتالي نمو الأجور تقريبًا. ويرى بيكيتي أن عائد رأس المال كان عبر معظم التاريخ أعلى من نمو الاقتصاد. وإذا استمر ذلك، فإن الثروات الموروثة تنمو أسرع من دخل من يعيشون على عملهم، فتتركز الثروة في يد قلة جيلًا بعد جيل.\n\nويرى أن الفترة بين الحربين العالميتين والسبعينيات، حين قلّ التفاوت، كانت استثناء سببه الحروب والأزمات والضرائب المرتفعة. حقق الكتاب مبيعات ضخمة رغم أنه كتاب اقتصاد طويل، وأثار جدلًا واسعًا، وانتقد اقتصاديون كثيرون بعض بياناته واستنتاجاته وما اقترحه من ضرائب على الثروة."},
{id:"harford-1",d:4,en:"The Undercover Economist",a:"Tim Harford",t:"لماذا القهوة أغلى بجوار المحطة؟",
x:"يبدأ تيم هارفورد كتابه بسؤال يومي: لماذا يدفع الناس سعرًا مرتفعًا لفنجان قهوة في مقهى بجوار محطة قطارات مزدحمة في لندن؟ قد تظن أن صاحب المقهى هو من يربح أكثر، لكن هارفورد يوضح أن الجزء الأكبر من هذا الربح يذهب في الغالب إلى صاحب المكان.\n\nالسبب هو الندرة. فالمواقع القريبة من مخرج المحطة قليلة، والمسافرون المستعجلون لا يريدون المشي بعيدًا. هذه الندرة تمنح قوة لمن يملك الموقع، فيرفع الإيجار إلى أقصى ما يمكن أن يدفعه المقهى. أما القهوة نفسها والعمالة والأكواب فيمكن الحصول عليها في أي مكان، فلا تمنح أحدًا قوة كبيرة. وهي فكرة تعود إلى الاقتصادي ديفيد ريكاردو في القرن التاسع عشر حين تحدث عن الأرض الزراعية الخصبة.\n\nالدرس: لكي تعرف من يربح فعلًا في أي نشاط، ابحث عن الشيء النادر فيه، فمن يملكه يأخذ الحصة الكبرى."},
{id:"rosling-1",d:4,en:"Factfulness",a:"Hans Rosling",t:"الشمبانزي يتفوق علينا",
x:"كان هانز روسلينج طبيبًا وأستاذًا في الصحة العامة، وكان يطرح على جمهوره أسئلة بسيطة عن حال العالم، لكل منها ثلاث إجابات. مثلًا: خلال العشرين عامًا الماضية، ماذا حدث لنسبة سكان العالم الذين يعيشون في فقر مدقع؟ تضاعفت تقريبًا، أم بقيت كما هي، أم انخفضت إلى النصف تقريبًا؟\n\nالإجابة الصحيحة أنها انخفضت إلى النصف تقريبًا، لكن قلة قليلة من الناس اختاروها. ولاحظ روسلينج أن الناس، حتى المتعلمين والصحفيين والسياسيين، يجيبون عن هذه الأسئلة بشكل أسوأ مما لو اختاروا عشوائيًا. ولذلك كان يقول ساخرًا إن قردة الشمبانزي التي تختار عشوائيًا ستتفوق على البشر.\n\nالسبب أن عقولنا تميل إلى الأخبار السيئة والدرامية، وأن الإعلام ينقل الكوارث أكثر من التحسن البطيء. ولا يقول روسلينج إن العالم بخير تمامًا، بل إنه سيئ وأفضل من قبل في الوقت نفسه، وإن رؤية الحقائق بدقة شرط لحل المشكلات الحقيقية."},
{id:"beard-1",d:5,en:"SPQR",a:"Mary Beard",t:"اليوم الذي أصبح فيه الجميع رومانيين",
x:"تكتب المؤرخة البريطانية ماري بيرد تاريخ روما القديمة منذ تأسيسها الأسطوري حتى عام مئتين واثني عشر ميلادية، وتختار هذا العام بالذات نهاية لكتابها لسبب مهم.\n\nففي هذا العام أصدر الإمبراطور كاراكالا قرارًا منح فيه الجنسية الرومانية لكل الأحرار في الإمبراطورية تقريبًا، من بريطانيا إلى سوريا ومصر. وكانت الجنسية الرومانية قبل ذلك امتيازًا يحرص عليه الناس، ويحارب بعضهم من أجله، لأنها تمنح حقوقًا قانونية وحماية خاصة. وبين ليلة وضحاها صار عشرات الملايين مواطنين رومانيين، بعد قرون من التمييز بين المواطن وغيره.\n\nوترى بيرد أن هذا القرار غيّر معنى أن تكون رومانيًا. وتشير إلى أن المؤرخين يختلفون حول دوافعه، وأن من الأسباب التي تُذكر عادة رغبة الإمبراطور في زيادة عدد من يدفعون الضرائب الخاصة بالمواطنين. أما اسم الكتاب فهو اختصار لاتيني لعبارة مجلس الشيوخ وشعب روما."},
{id:"tuchman-1",d:5,en:"The Guns of August",a:"Barbara W. Tuchman",t:"الكتاب الذي قرأه كينيدي في أزمة الصواريخ",
x:"تروي المؤرخة باربرا توكمان الشهر الأول من الحرب العالمية الأولى عام ألف وتسعمئة وأربعة عشر، وكيف دخلت دول أوروبا الكبرى حربًا لم يكن أحد يريدها بهذا الحجم.\n\nكانت كل دولة تملك خطة عسكرية جاهزة، وكان كل جانب واثقًا من أن الحرب ستكون قصيرة، وأن الجنود سيعودون إلى بيوتهم قبل أن تتساقط أوراق الخريف. لكن الخطط المعقدة، وسوء فهم كل طرف لنوايا الآخر، وسرعة التعبئة العسكرية، جعلت الأحداث تتدحرج خارج سيطرة القادة، فتحولت إلى حرب استمرت أربع سنوات وقتلت الملايين.\n\nنُشر الكتاب عام ألف وتسعمئة واثنين وستين وحصل على جائزة بوليتزر. وفي العام نفسه، خلال أزمة الصواريخ الكوبية، تأثر الرئيس الأمريكي جون كينيدي بالكتاب، وكان حريصًا على ألا يدفع سوء التقدير والخطط الجامدة العالم إلى حرب لا يريدها أحد، كما حدث في أغسطس ألف وتسعمئة وأربعة عشر."},
{id:"marshall-1",d:5,en:"Prisoners of Geography",a:"Tim Marshall",t:"لماذا تخاف روسيا من السهول؟",
x:"يرى الصحفي تيم مارشال أن قادة الدول، مهما كانت أفكارهم، يبقون أسرى للجغرافيا: للجبال والأنهار والبحار التي تحدد ما يمكنهم فعله.\n\nومن أوضح أمثلته روسيا. فغرب روسيا يقع على سهل واسع منبسط يمتد من فرنسا مرورًا ببولندا حتى موسكو، دون جبال كبيرة تعترض الجيوش. ومن هذا السهل غزا نابليون روسيا عام ألف وثمانمئة واثني عشر، وغزاها هتلر عام ألف وتسعمئة وواحد وأربعين. لذلك ظلت روسيا عبر تاريخها تحاول أن تدفع حدودها غربًا، أو أن تحيط نفسها بدول تابعة، لتبعد الخطر عن قلبها.\n\nوالمشكلة الثانية عند روسيا هي الموانئ. فمعظم موانئها الشمالية تتجمد شهورًا في السنة، لذلك تهتم كثيرًا بالموانئ الدافئة، مثل سيفاستوبول في شبه جزيرة القرم على البحر الأسود. ويرى مارشال أن فهم هذه الخريطة يساعد على فهم كثير من سياسات روسيا اليوم."},
{id:"sagan-1",d:6,en:"Cosmos",a:"Carl Sagan",t:"رجل من الإسكندرية قاس الأرض بعصا",
x:"يحكي كارل ساجان قصة إراتوستينس، العالم الذي كان مسؤولًا عن مكتبة الإسكندرية في القرن الثالث قبل الميلاد. قرأ إراتوستينس أن الشمس في مدينة أسوان، في جنوب مصر، تكون عمودية تمامًا ظهيرة يوم معين من الصيف، فتضيء قاع البئر العميقة، ولا تُلقي العصا المغروسة في الأرض أي ظل.\n\nفغرس عصا في الإسكندرية في اليوم نفسه والساعة نفسها، فوجد أنها تلقي ظلًا واضحًا بزاوية نحو سبع درجات. استنتج إراتوستينس أن هذا الفرق لا يمكن تفسيره إلا إذا كانت الأرض كروية. وبما أن سبع درجات تساوي تقريبًا جزءًا من خمسين من الدائرة الكاملة، فإن محيط الأرض يساوي خمسين ضعف المسافة بين المدينتين. فاستأجر شخصًا يقيس المسافة بالخطوات، وكانت نحو ثمانمئة كيلومتر، فخرج بمحيط للأرض قريب جدًا من الرقم الحقيقي، نحو أربعين ألف كيلومتر.\n\nكل هذا بعصيّ وظلال وتفكير دقيق، قبل أكثر من ألفي عام."},
{id:"bryson-1",d:6,en:"A Short History of Nearly Everything",a:"Bill Bryson",t:"العالم الذي قاس عمر الأرض فاكتشف الرصاص",
x:"يحكي بيل برايسون قصة العالم الأمريكي كلير باترسون، الذي حاول في أربعينيات وخمسينيات القرن العشرين تحديد عمر الأرض بقياس الرصاص في صخور قديمة ونيازك.\n\nواجه باترسون مشكلة غريبة: كانت عيناته تتلوث بالرصاص دائمًا، مهما حاول أن يعمل بنظافة. فبنى واحدًا من أنظف المختبرات في العالم، وتمكّن عام ألف وتسعمئة وثلاثة وخمسين من حساب عمر الأرض: نحو أربعة مليارات ونصف المليار سنة، وهو الرقم المقبول حتى اليوم.\n\nلكن السؤال بقي: من أين يأتي كل هذا الرصاص؟ اكتشف باترسون أنه موجود في كل مكان تقريبًا، في الهواء والماء ودماء البشر، وأن مصدره الأكبر هو البنزين المضاف إليه الرصاص، الذي كانت شركات الوقود تبيعه منذ العشرينيات. فخاض معركة طويلة مع هذه الصناعة القوية، وحاولت جهات عديدة إسكاته، لكن أبحاثه ساهمت في النهاية في منع البنزين المحتوي على الرصاص في الولايات المتحدة ثم في معظم العالم."},
{id:"tyson-1",d:6,en:"Astrophysics for People in a Hurry",a:"Neil deGrasse Tyson",t:"نحن مصنوعون من مادة النجوم",
x:"يقدّم نيل ديجراس تايسون في كتاب قصير أفكارًا كبرى عن الكون، ومن أجملها ملاحظة بسيطة عن العناصر.\n\nإذا رتبت العناصر حسب كثرتها في الكون كله، واستبعدت الهيليوم لأنه لا يتفاعل كيميائيًا تقريبًا، فإن أكثر أربعة عناصر شيوعًا هي الهيدروجين والأكسجين والكربون والنيتروجين. وهذه بالضبط هي العناصر الأربعة الأكثر وجودًا في الكائنات الحية، ومنها جسمك أنت.\n\nوالأغرب أن معظم هذه العناصر، ما عدا الهيدروجين، لم تكن موجودة في بداية الكون، بل صُنعت في قلوب النجوم من خلال الاندماج النووي. وحين انفجرت النجوم الكبيرة في نهاية حياتها، نثرت هذه العناصر في الفضاء، فتكوّنت منها نجوم وكواكب جديدة، ومنها الأرض وكل ما عليها.\n\nلذلك يقول تايسون إننا لسنا مجرد سكان في الكون، بل جزء منه، وإن ذرات الكربون في خلاياك والحديد في دمك صُنعت ذات يوم داخل نجم."},
{id:"plato-1",d:7,en:"The Republic",a:"Plato",t:"الكهف",
x:"في كتاب الجمهورية يطلب أفلاطون، على لسان أستاذه سقراط، أن نتخيل أناسًا مقيّدين منذ ولادتهم داخل كهف، ووجوههم نحو الجدار. خلفهم نار، وبين النار وظهورهم يمر أشخاص يحملون أشياء مختلفة، فتظهر ظلالها على الجدار. لم ير هؤلاء السجناء شيئًا في حياتهم إلا الظلال، فيظنون أنها الحقيقة كلها.\n\nثم يتحرر أحدهم، ويلتفت فيرى النار، ثم يخرج من الكهف إلى ضوء الشمس. في البداية يتألم من الضوء ولا يستطيع الرؤية، ثم يرى العالم الحقيقي تدريجيًا، ويدرك أن ما كان يراه مجرد ظلال. فيعود إلى الكهف ليخبر أصحابه، فلا يصدقونه، بل يسخرون منه، وربما يحاولون قتله لو استطاعوا.\n\nأراد أفلاطون أن يقول إن معظم الناس يعيشون مع انطباعات سطحية يظنونها الحقيقة، وإن طريق المعرفة مؤلم في البداية، وإن من يرى أبعد كثيرًا ما يواجه رفض الآخرين. ويرى كثيرون أن القصة تلمّح إلى إعدام سقراط نفسه."},
{id:"suntzu-1",d:7,en:"The Art of War",a:"Sun Tzu",t:"أن تنتصر دون أن تقاتل",
x:"كتاب فن الحرب نص صيني قديم يُنسب إلى القائد العسكري سون تزو، ويعود إلى نحو ألفين وخمسمئة عام. ورغم أنه كتاب عن الحرب، فإن أشهر أفكاره تقول إن أفضل انتصار هو الذي لا تحتاج فيه إلى القتال أصلًا.\n\nيقول سون تزو إن الانتصار في مئة معركة ليس قمة المهارة، بل قمة المهارة أن تكسر مقاومة عدوك دون قتال. فالقتال مكلف، حتى لو انتصرت فيه، والقائد الحكيم يحقق هدفه بالتخطيط والحيلة والتحالفات، وبإظهار أن مقاومته لا فائدة منها.\n\nومن عباراته الشهيرة أيضًا: إذا عرفت عدوك وعرفت نفسك فلن تخشى نتيجة مئة معركة، وإذا عرفت نفسك ولم تعرف عدوك فستنتصر مرة وتنهزم مرة، وإذا لم تعرف هذا ولا ذاك فستنهزم في كل معركة. لهذا يُقرأ الكتاب اليوم في الإدارة والتفاوض والرياضة والسياسة، لا في الحروب فقط."},
{id:"camus-1",d:7,en:"The Myth of Sisyphus",a:"Albert Camus",t:"يجب أن نتخيل سيزيف سعيدًا",
x:"في الأسطورة اليونانية عاقبت الآلهة سيزيف بأن يدفع صخرة ضخمة إلى قمة جبل، وكلما وصل إلى القمة تدحرجت الصخرة إلى الأسفل، فيعود ليدفعها من جديد، إلى الأبد.\n\nاستخدم الكاتب والفيلسوف الفرنسي ألبير كامو هذه الأسطورة ليشرح فكرة سمّاها العبث: الإنسان يبحث بشغف عن معنى ووضوح، والكون من حوله صامت لا يعطيه جوابًا نهائيًا. وهذا التناقض بين ما نريده وما نجده هو العبث.\n\nلكن كامو لا يدعو إلى اليأس. فهو يرى أن اللحظة الأهم في القصة هي حين ينزل سيزيف من القمة ليعود إلى صخرته، واعيًا تمامًا بمصيره. في هذه اللحظة يكون أقوى من عقابه، لأنه يقبل التحدي ويختار أن يستمر. ولذلك ينهي كامو مقاله بعبارته الشهيرة: يجب أن نتخيل سيزيف سعيدًا. فالكفاح نفسه نحو القمة يكفي لملء قلب الإنسان."},
{id:"ratey-1",d:8,en:"Spark",a:"John J. Ratey",t:"الرياضة سماد للدماغ",
x:"يرى الطبيب النفسي جون ريتي، الأستاذ في جامعة هارفارد، أن أهم فوائد الرياضة ليست للعضلات ولا للقلب، بل للدماغ.\n\nفعند التمرين يفرز الجسم بروتينًا اسمه العامل العصبي المشتق من الدماغ، ويصفه ريتي بأنه سماد للدماغ، لأنه يساعد الخلايا العصبية على النمو وتكوين روابط جديدة، خاصة في المناطق المسؤولة عن التعلم والذاكرة. كما تساعد الرياضة على تخفيف التوتر والقلق وتحسين المزاج.\n\nومن أمثلته مدرسة ثانوية في مدينة نابرفيل الأمريكية غيّرت حصص الرياضة: بدل التركيز على الألعاب والمنافسة، صار الطلاب يمارسون تمارين تقيس نبضات القلب، وكل طالب يحاول تحسين لياقته هو، لا التفوق على غيره. وأضافت المدرسة حصة رياضة صباحية قبل أصعب المواد الدراسية. ويذكر ريتي أن طلاب المنطقة حققوا بعدها نتائج متقدمة جدًا في اختبار دولي للعلوم والرياضيات.\n\nالدرس العملي: إذا كان أمامك عمل يحتاج إلى تركيز، فقد يكون التمرين قبله أفضل استعداد."},
{id:"mcdougall-1",d:8,en:"Born to Run",a:"Christopher McDougall",t:"قبيلة تركض مئات الكيلومترات بصندل",
x:"بدأ كريستوفر ماكدوجال رحلته بسؤال بسيط: لماذا تؤلمني قدمي حين أركض؟ وقاده السؤال إلى قبيلة التاراهومارا التي تعيش في أخاديد نائية في المكسيك، ويُعرف أفرادها بقدرتهم على الركض مسافات طويلة جدًا، أحيانًا مئات الكيلومترات، وهم يرتدون صنادل بسيطة مصنوعة من إطارات السيارات.\n\nويطرح ماكدوجال فكرة أن الإنسان خُلق ليركض. فبعض العلماء يرون أن أسلافنا كانوا يصطادون بطريقة تسمى صيد المطاردة: يركضون خلف الحيوان ساعات طويلة في الحر، حتى يسقط من الإرهاق، لأن الإنسان يستطيع التعرق والتبريد أثناء الركض بينما لا تستطيع أغلب الحيوانات ذلك.\n\nكما ينتقد الأحذية الرياضية المبطنة جدًا، ويرى أنها غيّرت طريقة ركض الناس فزادت الإصابات. أطلق الكتاب موجة كبيرة من الركض بأحذية خفيفة أو حافيًا، لكن الدراسات اللاحقة لم تحسم بعد أي الطريقتين أفضل، ومن يرغب في التغيير ينصحه الخبراء بالتدرج."},
{id:"lembke-1",d:8,en:"Dopamine Nation",a:"Anna Lembke",t:"ميزان المتعة والألم",
x:"تعمل آنا لمبكي طبيبة نفسية في جامعة ستانفورد، وتعالج حالات الإدمان. وتشرح في كتابها أن الدماغ يعالج المتعة والألم في المناطق نفسها تقريبًا، وكأن بداخله ميزانًا: كفة للمتعة وكفة للألم.\n\nحين تحصل على متعة سريعة، كتصفح الهاتف أو الحلويات أو الألعاب، يميل الميزان نحو المتعة. لكن الدماغ يحاول دائمًا أن يعيد التوازن، فيضيف وزنًا إلى كفة الألم. ولهذا تشعر بعد المتعة بشيء من الفراغ والرغبة في المزيد. ومع التكرار يصبح هذا الوزن على كفة الألم دائمًا، فتحتاج إلى متعة أكبر لتشعر بالشعور نفسه، وتشعر بالضيق حين تتوقف.\n\nوالمدهش أن العكس صحيح أيضًا. فالأشياء التي تبدأ بقليل من الألم، كالتمرين أو الماء البارد أو العمل الصعب، يرد عليها الدماغ بإضافة وزن إلى كفة المتعة، فتشعر بعدها بالراحة. وتقترح لمبكي لمن يشعر بأنه فقد السيطرة على عادة ما أن يمتنع عنها نحو شهر، ليعطي الميزان فرصة ليستعيد توازنه."},
{id:"patterson-1",d:9,en:"Crucial Conversations",a:"Patterson, Grenny, McMillan & Switzler",t:"اختيار الأحمق",
x:"يعرّف مؤلفو الكتاب المحادثة الحاسمة بأنها محادثة فيها ثلاثة عناصر: الآراء مختلفة، والمخاطر عالية، والمشاعر قوية. مثل الحديث مع مديرك عن تقييم ظالم، أو مع شريك حياتك عن المال.\n\nوفي هذه المواقف يقع كثير من الناس في ما يسميه المؤلفون اختيار الأحمق: أن تظن أن أمامك خيارين فقط. إما أن تكون صريحًا وتقول الحقيقة فتجرح الآخر وتخسر العلاقة، وإما أن تحافظ على العلاقة فتسكت وتكتم ما بداخلك. ويرى المؤلفون أن هذا تقسيم خاطئ، وأن المتحدثين المهرة يبحثون عن خيار ثالث: أن يقولوا الحقيقة كاملة، وبطريقة تحفظ الاحترام في الوقت نفسه.\n\nومن أدواتهم سؤال بسيط تطرحه على نفسك قبل الكلام: ماذا أريد حقًا لنفسي، وللطرف الآخر، وللعلاقة؟ هذا السؤال يمنعك من أن تتحول رغبتك في الفوز بالنقاش إلى هدف بديل عن هدفك الحقيقي."},
{id:"goleman-1",d:9,en:"Emotional Intelligence",a:"Daniel Goleman",t:"حين يختطف الغضب عقلك",
x:"يشرح دانيال جولمان أن في الدماغ منطقة صغيرة اسمها اللوزة الدماغية، تعمل كجهاز إنذار سريع. حين ترى خطرًا، أو تشعر بإهانة، تستطيع هذه المنطقة أن تطلق ردة فعل عاطفية قوية قبل أن يكمل الجزء المفكر من الدماغ تحليل الموقف.\n\nويسمي جولمان هذه اللحظة اختطاف اللوزة الدماغية: تنفجر غضبًا في وجه شخص، أو ترسل رسالة حادة، ثم تهدأ بعد دقائق وتتساءل لماذا فعلت ذلك. هذه الآلية كانت مفيدة لأسلافنا حين كانت المخاطر حيوانات مفترسة، لكنها اليوم تسبب مشكلات في العمل والعلاقات.\n\nومن هنا فكرة الكتاب الأساسية: الذكاء العاطفي، أي القدرة على فهم مشاعرك ومشاعر الآخرين والتحكم في ردود أفعالك، مهارة يمكن تعلمها، ويرى جولمان أنها تؤثر في النجاح بقدر يقارب ما يؤثر فيه الذكاء التقليدي أو أكثر. ومن أبسط تطبيقاتها: حين تشعر بالغضب، أجّل الرد بضع دقائق حتى يلحق عقلك المفكر بمشاعرك."},
{id:"gladwell-1",d:9,en:"Talking to Strangers",a:"Malcolm Gladwell",t:"لماذا نصدّق الكاذبين؟",
x:"يسأل مالكولم جلادويل: لماذا نفشل كثيرًا في فهم الغرباء، رغم أننا نعتقد أننا نقرأ الناس جيدًا؟\n\nومن أمثلته رئيس وزراء بريطانيا نيفيل تشامبرلين، الذي سافر إلى ألمانيا عام ألف وتسعمئة وثمانية وثلاثين وقابل هتلر بنفسه، ثم عاد مقتنعًا بأنه رجل يمكن الوثوق بكلمته. ويلاحظ جلادويل أن كثيرًا ممن قابلوا هتلر شخصيًا أخطأوا في تقديره، بينما كان بعض من لم يقابلوه أكثر شكًا فيه.\n\nويعتمد جلادويل على أبحاث عالم النفس تيم ليفين، الذي يرى أن البشر يميلون بطبيعتهم إلى افتراض الصدق، أي أننا نصدق الآخرين تلقائيًا حتى تتراكم أدلة قوية جدًا على الكذب. وهذه الصفة ليست غباء، بل هي ما يجعل الحياة الاجتماعية ممكنة، فلو شككنا في كل شخص لما استطعنا التعامل مع أحد. لكن ثمنها أن المحتالين ينجحون أحيانًا لفترات طويلة. الدرس: الانطباع من لقاء واحد أقل دقة مما نظن، فلا تبنِ عليه وحده القرارات المهمة."},
{id:"franklin-1",d:10,en:"The Autobiography of Benjamin Franklin",a:"Benjamin Franklin",t:"ثلاث عشرة فضيلة وجدول صغير",
x:"كان بنجامين فرانكلين كاتبًا وعالمًا ومخترعًا وأحد مؤسسي الولايات المتحدة. ويحكي في سيرته الذاتية أنه قرر في شبابه أن يصل إلى ما سماه الكمال الأخلاقي، فاكتشف بسرعة أن الأمر أصعب مما ظن، لأنه كلما ركز على عيب، ظهر عيب آخر.\n\nفوضع خطة عملية: اختار ثلاث عشرة فضيلة، منها الاعتدال في الطعام، وقلة الكلام فيما لا يفيد، والنظام، والعزم، والتوفير، والاجتهاد، والصدق. ثم صنع دفترًا صغيرًا فيه جدول، أيام الأسبوع في الأعمدة والفضائل في الصفوف، وكان يضع نقطة كلما أخطأ في فضيلة منها.\n\nوالمهم في طريقته أنه لم يحاول أن يتقن كل الفضائل دفعة واحدة، بل كان يركز على فضيلة واحدة كل أسبوع، فيدور على الثلاث عشرة في ثلاثة عشر أسبوعًا، ثم يبدأ الدورة من جديد. ويعترف بأنه لم يصل إلى الكمال أبدًا، لكنه يقول إن المحاولة جعلته إنسانًا أفضل وأسعد مما لو لم يحاول."},
{id:"agassi-1",d:10,en:"Open",a:"Andre Agassi",t:"البطل الذي كره التنس",
x:"أندريه أجاسي من أعظم لاعبي التنس في التاريخ، فاز بثماني بطولات كبرى، وكان من القلائل الذين فازوا بالبطولات الأربع الكبرى جميعًا. لكن أول ما يعترف به في مذكراته هو أنه يكره التنس، بشغف مظلم وسري كما يقول.\n\nبدأت القصة مع والده، الذي قرر أن يجعل ابنه بطلًا عالميًا قبل أن يختار الابن أي شيء. فبنى في ساحة البيت ملعبًا، وصنع آلة تقذف الكرات بسرعة عالية سمّاها أندريه التنين. وكان الأب يحسب أن الطفل إذا ضرب ألفين وخمسمئة كرة يوميًا، فسيضرب نحو مليون كرة في السنة، ولن يستطيع أحد أن يهزمه.\n\nيحكي أجاسي كيف عاش سنوات طويلة يلعب لعبة لا يحبها، ويبحث عن هويته خارجها، حتى إنه كان يرتدي شعرًا مستعارًا في بداية مسيرته ليخفي تساقط شعره. ثم وجد معنى للعب حين ربطه بشيء يحبه، فأسس مدرسة لأطفال الأحياء الفقيرة، وصار يلعب من أجلها. الكتاب درس في أن النجاح الخارجي لا يعني السعادة الداخلية بالضرورة."},
{id:"westover-1",d:10,en:"Educated",a:"Tara Westover",t:"لم تدخل مدرسة حتى السابعة عشرة",
x:"نشأت تارا ويستوفر في جبال ولاية أيداهو الأمريكية، في أسرة يرفض فيها الأب المدارس الحكومية والمستشفيات، ويستعد دائمًا لنهاية العالم. لم تدخل تارا المدرسة يومًا، ولم يكن لها شهادة ميلاد حتى سن التاسعة، وقضت طفولتها تعمل مع والدها في جمع الخردة في ظروف خطيرة.\n\nوحين اقتربت من السابعة عشرة، قررت أن تحاول الالتحاق بالجامعة، متأثرة بأخ لها سبقها إلى ذلك. فعلّمت نفسها الرياضيات والقواعد من الكتب، ونجحت في اختبار القبول، والتحقت بجامعة بريجهام يونج. وفي إحدى محاضراتها الأولى سألت عن معنى كلمة الهولوكوست لأنها لم تسمع بها من قبل، فنظر إليها الطلاب بدهشة.\n\nلكنها استمرت، حتى حصلت لاحقًا على الدكتوراه في التاريخ من جامعة كامبريدج. وتحكي في مذكراتها أن أصعب ما في الرحلة لم يكن الدراسة، بل أن التعليم غيّر طريقة رؤيتها لأسرتها ولنفسها، وأنها دفعت ثمنًا كبيرًا في علاقتها بعائلتها. الكتاب عن قوة التعليم في أن يمنح الإنسان عقلًا خاصًا به."},
{id:"kishimi-1",d:0,en:"The Courage to Be Disliked",a:"Ichiro Kishimi & Fumitake Koga",t:"مهمة من هذه؟",
x:"كُتب هذا الكتاب الياباني على شكل حوار بين فيلسوف وشاب، ويشرح أفكار عالم النفس ألفرد أدلر. ومن أهم هذه الأفكار ما يسميه فصل المهام.\n\nحين تواجه مشكلة مع شخص آخر، اسأل: مهمة من هذه؟ والطريقة لمعرفة ذلك أن تسأل: من سيتحمل في النهاية نتيجة هذا القرار؟ مثال: الأب يريد أن يذاكر ابنه. لكن المذاكرة مهمة الابن، لأنه هو من سيتحمل نتيجة نجاحه أو رسوبه. يستطيع الأب أن يساعد ويشجع ويكون متاحًا، لكنه لا يستطيع أن يجبر ابنه على التعلم، ومحاولة فعل ذلك تفسد العلاقة غالبًا.\n\nوالأمر نفسه معك: رأي الناس فيك هو مهمتهم، لا مهمتك. مهمتك أن تعيش وفق ما تراه صحيحًا، أما أن يحبك الآخرون أو لا فليس في يدك. ومن هنا جاء عنوان الكتاب: الحرية الحقيقية تتطلب شجاعة أن يكرهك بعض الناس."},
{id:"shamani-1",d:1,en:"Build, Don't Talk",a:"Raj Shamani",t:"من مستهلك إلى منتِج",
x:"راج شاماني رائد أعمال ومقدم بودكاست هندي معروف، كتب هذا الكتاب عن الأشياء التي تمنى لو تعلمها في المدرسة: عن المال والعمل وبناء الذات.\n\nومن أهم أفكاره التحول من مستهلك إلى منتِج. المستهلك يقضي وقته وماله في أشياء صنعها غيره: يشاهد الفيديوهات، ويشتري المنتجات، ويتابع حياة الآخرين. أما المنتِج فيصنع شيئًا له قيمة يدفع الآخرون مقابله، سواء بالمال أو بالوقت أو بالانتباه. والثروة الحقيقية في رأيه لا تأتي من الاستهلاك الذكي، بل من الإنتاج.\n\nمثال بسيط: شخص يشاهد ساعتين يوميًا فيديوهات عن الطبخ، وآخر يقضي الوقت نفسه يصور وصفاته وينشرها. بعد سنة، الأول يعرف وصفات كثيرة، والثاني يملك جمهورًا ومهارة وربما دخلًا.\n\nويرى شاماني أن الأهداف الكبيرة لا تكفي وحدها، وأن ما يصنع الفرق هو العادات اليومية الصغيرة، وأن أصعب خطوة دائمًا هي أن تبدأ، ثم أن تستمر. ومن هنا عنوان الكتاب: ابنِ ولا تكتفِ بالكلام."},
{id:"robin-1",d:2,en:"Your Money or Your Life",a:"Vicki Robin & Joe Dominguez",t:"كم ساعة من حياتك ثمن هذا الشيء؟",
x:"يطلب هذا الكتاب أن تنظر إلى المال بطريقة مختلفة: المال هو شيء تبادله بطاقة حياتك، أي بساعات من عمرك لا تعود.\n\nلذلك يقترح المؤلفان أن تحسب أجرك الحقيقي في الساعة. ابدأ براتبك، ثم اطرح منه كل ما تنفقه بسبب العمل: المواصلات، وملابس العمل، والأكل خارج البيت لأنه لا وقت لديك للطبخ، وحتى المصروفات التي تنفقها لتعوض نفسك عن تعب الأسبوع. ثم أضف إلى ساعات العمل الرسمية وقت المواصلات والاستعداد والتعب بعد العمل. غالبًا ستكتشف أن أجرك الحقيقي في الساعة أقل بكثير مما كنت تظن.\n\nبعدها، قبل أي شراء، حوّل السعر إلى ساعات. فإذا كان أجرك الحقيقي عشرة يوروهات في الساعة، فإن هاتفًا بألف يورو يساوي مئة ساعة من حياتك. السؤال لم يعد: هل أستطيع شراءه؟ بل: هل يستحق مئة ساعة من عمري؟ كثير من الناس يكتشفون بهذه الطريقة أن نصف مشترياتهم لا تستحق."},
{id:"tracy-1",d:3,en:"The Psychology of Selling",a:"Brian Tracy",t:"دخلك لا يتجاوز صورتك عن نفسك",
x:"يرى براين تريسي، أحد أشهر مدربي المبيعات، أن الفرق الأكبر بين البائعين لا يكون في المهارات فقط، بل في ما يسميه مفهوم الذات، أي الصورة التي يحملها الشخص عن نفسه وعن قيمته.\n\nفكل بائع، كما يقول، يحمل في داخله رقمًا يرى أنه الدخل المناسب له، ومنطقة راحة حول هذا الرقم. إذا انخفض دخله عنها، يبذل جهدًا كبيرًا ليعود. وإذا ارتفع عنها فجأة، يبدأ دون وعي في التراخي أو ارتكاب الأخطاء حتى يعود إلى المستوى الذي يشعر أنه يستحقه. لذلك فإن تعلم تقنيات بيع جديدة دون تغيير الصورة الداخلية يعطي نتائج مؤقتة.\n\nويتحدث تريسي أيضًا عن الخوف من الرفض، ويراه أكبر عائق أمام البائعين. ونصيحته أن تفهم أن الرفض ليس موجهًا إليك شخصيًا، بل إلى العرض في هذا الوقت. والفكرة تتجاوز المبيعات: ما تحققه في أي مجال يرتبط غالبًا بما تعتقد أنك تستحقه."},
{id:"humm-1",d:3,en:"The StorySelling Method",a:"Philipp Humm",t:"أربع خطوات لقصة تبيع",
x:"يرى فيليب هوم أن الناس لا يشترون بسبب الأرقام والمواصفات وحدها، بل بسبب الثقة، وأن أسرع طريق للثقة هو القصة. لكن ليس أي قصة: القصة المؤثرة في البيع تدور حول شخص حقيقي، كمؤسس أو موظف أو عميل، لا حول الشركة ومنتجاتها.\n\nويقدم هيكلًا بسيطًا من أربع خطوات يصلح لأي قصة بيع. الأولى: السياق، أي من البطل وأين ومتى. الثانية: التحدي، أي المشكلة التي واجهها. الثالثة: الاستجابة، أي ما فعله لحلها، مع الاكتفاء بالخطوات المهمة. الرابعة: النتيجة، أي ما تغير بعد ذلك.\n\nقارن بين جملتين في هذا المثال. الأولى: برنامجنا يزيد الكفاءة بنسبة عشرين في المئة. والثانية: كانت سارة، مديرة التسويق في شركة تقنية، تقضي أيامها في جمع التقارير يدويًا، ولم يعد لديها وقت لفريقها. بدأنا معها بخطوة واحدة، وبعد ستة أشهر صار فريقها يقضي وقته في التخطيط بدل النسخ واللصق. المعلومة نفسها، لكن الثانية تبقى في الذاكرة. ويقترح هوم أن تتدرب على هذا الهيكل بأن تحكي لصديق حدثًا عاديًا من يومك بالخطوات الأربع."},
{id:"smith-1",d:4,en:"The Wealth of Nations",a:"Adam Smith",t:"مصنع الدبابيس",
x:"في عام ألف وسبعمئة وستة وسبعين نشر الفيلسوف الاسكتلندي آدم سميث كتابه ثروة الأمم، الذي يُعد أساس علم الاقتصاد الحديث. وبدأه بمثال صغير جدًا: مصنع للدبابيس.\n\nيقول سميث إن عاملًا واحدًا يصنع الدبوس كاملًا بنفسه، من سحب السلك إلى صنع الرأس، قد لا يصنع أكثر من دبوس واحد في اليوم، وبالتأكيد لن يصل إلى عشرين. لكنه رأى مصنعًا صغيرًا قُسّم فيه العمل إلى نحو ثماني عشرة خطوة منفصلة: عامل يسحب السلك، وآخر يقطعه، وثالث يبري طرفه، وهكذا. فكان عشرة عمال فقط ينتجون معًا نحو ثمانية وأربعين ألف دبوس في اليوم.\n\nهذا ما يسميه تقسيم العمل: حين يتخصص كل شخص في جزء صغير، يصبح أمهر فيه، ولا يضيع وقتًا في الانتقال بين المهام. ومن هنا انطلق سميث ليشرح كيف تزيد التجارة والتخصص ثروة الأمم كلها. لكنه حذّر أيضًا من أن تكرار مهمة بسيطة طوال الحياة قد يجعل العامل أقل تفكيرًا وإبداعًا."},
{id:"alkhalili-1",d:5,en:"The House of Wisdom",a:"Jim Al-Khalili",t:"الرجل الذي صار اسمه كلمة في كل حاسوب",
x:"يحكي عالم الفيزياء جيم الخليلي، العراقي البريطاني، قصة العصر الذهبي للعلم في الحضارة العربية الإسلامية، خاصة في بغداد في عهد الخلفاء العباسيين، حين صارت المدينة مركزًا لترجمة كتب اليونان والفرس والهند ودراستها والبناء عليها.\n\nومن أبرز شخصيات تلك الفترة محمد بن موسى الخوارزمي، الذي عمل في بغداد في القرن التاسع الميلادي. كتب الخوارزمي كتابًا في حل المعادلات بعنوان يبدأ بكلمتي الجبر والمقابلة، ومن كلمة الجبر جاء الاسم الذي يستخدمه العالم كله اليوم لهذا العلم: الجبر، أو ألجيبرا.\n\nأما اسمه هو، الخوارزمي، فحين تُرجمت كتبه إلى اللاتينية صار ألجوريتمي، ومنه جاءت كلمة الخوارزمية أو ألجوريذم، وهي الكلمة التي تصف اليوم كل خطوات الحل التي تعمل بها الحواسيب ومحركات البحث والذكاء الاصطناعي. كما ساعدت كتبه على نشر الأرقام الهندية العربية في أوروبا. ويرى الخليلي أن الغرب نسي طويلًا حجم ما يدين به لعلماء تلك الحقبة."},
{id:"carson-1",d:6,en:"Silent Spring",a:"Rachel Carson",t:"الربيع الذي لا تغني فيه الطيور",
x:"تبدأ عالمة الأحياء الأمريكية راشيل كارسون كتابها بحكاية عن بلدة جميلة جاءها الربيع صامتًا: لا طيور تغني، ولا نحل، والحيوانات مريضة. ثم تقول إن هذه البلدة غير موجودة، لكن كل ما حدث فيها حدث فعلًا في أماكن مختلفة.\n\nكان السبب في رأيها المبيدات الكيميائية، خاصة مبيد يسمى دي دي تي، الذي كان يُرش بكميات هائلة في الحقول والمدن. وشرحت كيف ينتقل المبيد من الحشرات إلى الديدان، ثم إلى الطيور التي تأكلها، ويتراكم في أجسامها مع الوقت، فيقتلها أو يضعف قدرتها على التكاثر.\n\nنُشر الكتاب عام ألف وتسعمئة واثنين وستين، وهاجمت شركات الكيماويات كارسون بشدة واتهمتها بالمبالغة. لكن الكتاب أثار نقاشًا عامًا واسعًا، وساهم في ولادة حركة حماية البيئة الحديثة، وفي منع استخدام هذا المبيد في الزراعة بالولايات المتحدة عام ألف وتسعمئة واثنين وسبعين. توفيت كارسون عام ألف وتسعمئة وأربعة وستين، قبل أن ترى أثر كتابها كاملًا."},
{id:"machiavelli-1",d:7,en:"The Prince",a:"Niccolò Machiavelli",t:"أن تُهاب أم أن تُحَب؟",
x:"كتب نيكولو مكيافيلي كتاب الأمير في فلورنسا بإيطاليا نحو عام ألف وخمسمئة وثلاثة عشر، بعد أن فقد منصبه السياسي، وأهداه إلى أحد حكام عائلة ميديشي. وبدل أن يصف الحاكم المثالي كما ينبغي أن يكون، وصف كيف تعمل السلطة في الواقع.\n\nومن أشهر أسئلته: هل الأفضل للحاكم أن يحبه الناس أم أن يخافوه؟ ويجيب بأن الأفضل أن يجمع الأمرين، لكن إن كان لا بد من الاختيار، فالأكثر أمانًا أن يخافوه. السبب في رأيه أن الحب رابطة يقطعها الناس حين تتعارض مع مصلحتهم، أما الخوف من العقاب فلا يتركهم.\n\nلكن مكيافيلي يضع شرطًا مهمًا كثيرًا ما يُنسى: يجب ألا يكرهه الناس. والطريق إلى ذلك أن يبتعد عن أموالهم وممتلكاتهم. لذلك صار اسمه مرادفًا للدهاء وأن الغاية تبرر الوسيلة، رغم أنه لم يكتب هذه العبارة بنصها. ويُقرأ الكتاب حتى اليوم لفهم السياسة والسلطة كما هي، لا كما نتمنى أن تكون."},
{id:"buettner-1",d:8,en:"The Blue Zones",a:"Dan Buettner",t:"توقّف عند ثمانين في المئة",
x:"زار الكاتب دان بوتنر مع فريق من الباحثين مناطق في العالم يعيش فيها عدد كبير من الناس حتى المئة عام بصحة جيدة، وسماها المناطق الزرقاء، ومنها أوكيناوا في اليابان، وجزيرة سردينيا في إيطاليا، وشبه جزيرة نيكويا في كوستاريكا، وجزيرة إيكاريا في اليونان.\n\nلاحظ أن هذه المناطق تشترك في عادات بسيطة. ففي أوكيناوا يردد كبار السن قبل الأكل عبارة معناها: كُل حتى تشبع بنسبة ثمانين في المئة فقط. فهم يتوقفون عن الأكل حين يشعرون بأنهم لم يعودوا جائعين، لا حين يمتلئون.\n\nومن العادات المشتركة أيضًا أن الناس هناك لا يذهبون إلى صالات الرياضة، لكنهم يتحركون طوال اليوم: يمشون، ويزرعون، ويصعدون التلال. ويأكلون كثيرًا من البقوليات والخضروات، ويقضون وقتًا طويلًا مع العائلة والأصدقاء، ولكل منهم سبب واضح يستيقظ من أجله. وفي أوكيناوا تجتمع مجموعات صغيرة من الأصدقاء مدى الحياة يدعم بعضهم بعضًا. والدرس أن طول العمر لا يأتي من حمية صارمة، بل من بيئة تجعل العادات الصحية سهلة وتلقائية."},
{id:"ferrazzi-1",d:9,en:"Never Eat Alone",a:"Keith Ferrazzi",t:"احفر البئر قبل أن تعطش",
x:"يرى كيث فيرازي أن معظم الناس يفهمون العلاقات المهنية بطريقة خاطئة: لا يتواصلون مع أحد إلا حين يحتاجون إلى شيء، كوظيفة أو خدمة أو توصية. وحينها يكون الوقت قد فات، لأن الطلب من شخص لم تتواصل معه منذ سنوات يبدو مصلحة واضحة.\n\nلذلك ينصح بأن تبني علاقاتك قبل أن تحتاج إليها، وأن يكون الأساس هو العطاء لا الأخذ. اسأل نفسك عن كل شخص تعرفه: كيف يمكنني أن أساعده؟ قد يكون ذلك بتعريفه على شخص يفيده، أو بإرسال مقال يهمه، أو بتهنئته على إنجاز، أو بنصيحة في مجالك. ولا تحسب ما أعطيت وما أخذت، لأن العلاقات ليست حسابًا بنكيًا.\n\nأما عنوان الكتاب فمعناه ألا تأكل وحدك، أي أن تستغل الوجبات واللقاءات اليومية لتقوية علاقاتك. وفكرته الأساسية أن الناس لا يساعدون من يعرفون اسمه فقط، بل من يعرفونه ويثقون به ويشعرون بأنه ساعدهم يومًا."},
{id:"dicks-1",d:9,en:"Storyworthy",a:"Matthew Dicks",t:"واجب الحياة اليومي",
x:"ماثيو ديكس معلم أمريكي فاز مرات كثيرة في مسابقات حكي القصص الحية. ويقول إن الناس يظنون أن حياتهم مملة ولا تحتوي على قصص، والحقيقة أنهم لا ينتبهون إلى القصص التي تمر بهم كل يوم.\n\nلذلك يقترح تمرينًا سماه واجب الحياة اليومي: في نهاية كل يوم، خصص خمس دقائق واكتب جملة أو جملتين عن أكثر لحظة في يومك تستحق أن تُحكى. ليس حدثًا كبيرًا بالضرورة، بل لحظة صغيرة: حوار غريب مع بائع، أو موقف جعلك تفهم شيئًا عن نفسك. بعد أسابيع ستلاحظ أنك صرت ترى القصص في كل مكان، وستملك مخزونًا منها.\n\nويرى ديكس أيضًا أن كل قصة جيدة، مهما طالت، تدور حول لحظة واحدة يسميها لحظة الخمس ثوانٍ: اللحظة التي يتغير فيها شيء داخل الراوي، كأن يفهم أمرًا أو يحب أو يقرر. والقصة كلها يجب أن تُبنى لتوصلك إلى هذه اللحظة. لذلك اسأل نفسك قبل أن تحكي أي قصة: ما الذي تغير فيّ؟"},
{id:"noah-1",d:10,en:"Born a Crime",a:"Trevor Noah",t:"وُلد جريمة",
x:"وُلد الكوميدي ومقدم البرامج تريفور نوح عام ألف وتسعمئة وأربعة وثمانين في جنوب أفريقيا، في زمن نظام الفصل العنصري، لأم سوداء وأب سويسري أبيض. وكان القانون في ذلك الوقت يمنع العلاقة بين شخص أبيض وشخص أسود ويعاقب عليها، لذلك كان مجرد وجوده مخالفة للقانون. ومن هنا جاء عنوان الكتاب: وُلد جريمة.\n\nفي طفولته لم يكن يستطيع أن يمشي في الشارع مع والديه معًا، وكانت أمه أحيانًا تتظاهر في الأماكن العامة بأنها ليست أمه، كي لا تلفت الانتباه.\n\nومن أجمل أفكار الكتاب ما تعلمه عن اللغة. فقد نشأ وهو يتحدث عدة لغات، منها الإنجليزية والأفريكانية ولغات أفريقية مثل الزوسا والزولو. ولاحظ أنه حين يتحدث مع الناس بلغتهم، يتعاملون معه كواحد منهم، حتى لو كان لونه مختلفًا. وصار يقول إن اللغة، أكثر من اللون، هي ما يحدد لدى الناس من أنت. وتظهر في الكتاب أيضًا شخصية أمه القوية، التي كانت ترفض أن تحدد لها القوانين حدود حياتها."}
];
